import fs from 'node:fs';import vm from 'node:vm';import assert from 'node:assert/strict';
let begun=0,closed=0;const app={beginUndoGroup(){begun++;},endUndoGroup(){closed++;}};
const ctx=vm.createContext({app});vm.runInContext(fs.readFileSync('src/rename.jsx','utf8'),ctx);
const layer={name:'Before'};ctx.renameLayer(layer,'After');assert.equal(layer.name,'After');assert.equal(begun,1);assert.equal(closed,1);
let mutated='Before';const partial={};Object.defineProperty(partial,'name',{set(value){mutated=value;throw new Error('failure after mutation');}});
assert.throws(()=>ctx.renameLayer(partial,'Partial'));assert.equal(closed,2,'close group after exception');assert.equal(mutated,'Partial','closing group is not rollback');
assert.throws(()=>ctx.renameLayer(null,'Absent'));assert.equal(begun,2,'reject missing selection before mutation');
console.log('PASS: synthetic group lifecycle only; no AE Undo/Redo claim');

import fs from 'node:fs';import vm from 'node:vm';import assert from 'node:assert/strict';
let begun=0,closed=0;const app={beginUndoGroup(){begun++;},endUndoGroup(){closed++;}};
const ctx=vm.createContext({app});vm.runInContext(fs.readFileSync('src/rename.jsx','utf8'),ctx);
const layer={name:'Before'};ctx.renameLayer(layer,'After');assert.equal(layer.name,'After');assert.equal(begun,1);assert.equal(closed,1);
let mutated='Before';const partial={};Object.defineProperty(partial,'name',{set(value){mutated=value;throw new Error('failure after mutation');}});
assert.throws(()=>ctx.renameLayer(partial,'Partial'));assert.equal(closed,2,'close group after exception');assert.equal(mutated,'Partial','closing group is not rollback');
assert.throws(()=>ctx.renameLayer(null,'Absent'));assert.equal(begun,2,'reject missing selection before mutation');
ctx.app={beginUndoGroup(){throw new Error('opening failed');},endUndoGroup(){closed++;}};
assert.throws(()=>ctx.renameLayer(layer,'No mutation'));assert.equal(layer.name,'After');assert.equal(closed,2,'never close an unopened group');
console.log('PASS: synthetic group lifecycle only; no AE Undo/Redo claim');

